import core/trusted/layer_declaration
axiomLayer "tools"
{.push raises: [].}
## Cleanup tool for auto-generated shadow files.
##
## Scans src/ for *_shadow.nim files, compares with originals,
## and identifies candidates that differ only by proc→func changes.
##
## Usage:
##   bin/cleanup_auto_shadows              # dry-run (default)
##   bin/cleanup_auto_shadows --delete     # actually delete
##   bin/cleanup_auto_shadows --verbose    # show per-file details

import std/[os, strutils, algorithm, tables, sequtils]

const
  ShadowSuffix = "_shadow"
  MinLinesForAutoGen = 16  # Files with <= 15 lines are forwarding stubs (skip)

type
  Category = enum
    catAutoGenerated    # proc→func only
    catForwardingStub   # <= 15 lines, import/export only
    catGateRunner       # in src/gate/runners/
    catOther            # everything else

  ShadowInfo = object
    shadowPath: string
    originalPath: string
    originalExists: bool
    category: Category
    shadowLines: int
    originalLines: int
    procFuncOnlyDiff: bool  # true if only proc→func differs
    reason: string          # why categorized this way

proc categorize(path: string, lineCount: int): Category =
  if path.contains("/gate/runners/") and path.endsWith("_shadow.nim"):
    return catGateRunner
  if lineCount <= 15:
    return catForwardingStub
  return catOther

proc diffProcFuncOnly(orig, shadow: string): bool =
  ## Check if the only difference between two files is proc→func substitutions.
  let origLines = orig.splitLines()
  let shadowLines = shadow.splitLines()

  if origLines.len != shadowLines.len:
    return false

  for i in 0 ..< origLines.len:
    let ol = origLines[i]
    let sl = shadowLines[i]
    if ol == sl:
      continue
    # Check if this line is a proc→func substitution
    let procIdx = ol.find("proc ")
    if procIdx >= 0 and (procIdx == 0 or not ol[procIdx - 1].isAlphaNumeric()):
      let expected = ol[0 ..< procIdx] & "func " & ol[procIdx + 5 .. ^1]
      if sl != expected:
        return false
    else:
      return false
  true

proc collectShadowFiles(srcDir: string): seq[string] {.raises: [CatchableError].} =
  for path in walkDirRec(srcDir):
    if path.endsWith("_shadow.nim"):
      result.add(path)
  result.sort()

proc lineCount(path: string): int =
  try:
    let content = readFile(path)
    content.splitLines().len
  except IOError:
    0

proc main() {.raises: [CatchableError].} =
  let toolDir = parentDir(currentSourcePath())
  let repoRoot = parentDir(toolDir)
  let srcDir = repoRoot / "src"

  let args = commandLineParams()
  let deleteMode = "--delete" in args
  let verbose = "--verbose" in args

  stderr.writeLine("cleanup_auto_shadows: scanning ", srcDir)

  let shadowPaths = collectShadowFiles(srcDir)
  stderr.writeLine("  Found ", shadowPaths.len, " shadow files")

  var infos: seq[ShadowInfo]
  var counts: Table[Category, int]

  for cat in Category:
    counts[cat] = 0

  for sp in shadowPaths:
    let lines = lineCount(sp)
    let cat = categorize(sp, lines)
    let origPath = sp.replace("_shadow.nim", ".nim")
    let origExists = fileExists(origPath)

    var info = ShadowInfo(
      shadowPath: sp,
      originalPath: origPath,
      originalExists: origExists,
      category: cat,
      shadowLines: lines,
      originalLines: if origExists: lineCount(origPath) else: 0,
      procFuncOnlyDiff: false,
      reason: ""
    )

    if cat == catForwardingStub:
      info.reason = "forwarding stub (<=" & $15 & " lines)"
      counts[catForwardingStub] += 1
    elif cat == catGateRunner:
      info.reason = "gate runner shadow (needs explicit confirmation)"
      counts[catGateRunner] += 1
    elif not origExists:
      info.reason = "no corresponding original file"
      counts[catOther] += 1
    else:
      # Compare content
      try:
        let origContent = readFile(origPath)
        let shadowContent = readFile(sp)
        if diffProcFuncOnly(origContent, shadowContent):
          info.procFuncOnlyDiff = true
          info.category = catAutoGenerated
          info.reason = "auto-generated (proc→func only)"
          counts[catAutoGenerated] += 1
        else:
          info.reason = "content differs beyond proc→func"
          counts[catOther] += 1
      except IOError:
        info.reason = "read error"
        counts[catOther] += 1

    infos.add(info)

  # Summary report
  echo "=== Shadow File Analysis Report ==="
  echo ""
  echo "Total shadow files: ", shadowPaths.len
  echo ""
  echo "Categories:"
  echo "  Auto-generated (proc→func only):  ", counts[catAutoGenerated]
  echo "  Forwarding stubs (<=15 lines):    ", counts[catForwardingStub]
  echo "  Gate runner shadows:              ", counts[catGateRunner]
  echo "  Other (manual/complex):           ", counts[catOther]
  echo ""

  # List auto-generated candidates
  let autoGen = infos.filterIt(it.category == catAutoGenerated)
  if autoGen.len > 0:
    echo "=== Auto-Generated Shadow Files (safe to delete) ==="
    for info in autoGen:
      let relShadow = info.shadowPath.replace(repoRoot & "/", "")
      let relOrig = info.originalPath.replace(repoRoot & "/", "")
      echo "  ", relOrig, " -> ", relShadow, " (", info.shadowLines, " lines)"
    echo ""

  # List forwarding stubs (informational only)
  let stubs = infos.filterIt(it.category == catForwardingStub)
  if stubs.len > 0:
    echo "=== Forwarding Stubs (NOT auto-generated, skip) ==="
    if verbose:
      for info in stubs:
        let relShadow = info.shadowPath.replace(repoRoot & "/", "")
        echo "  ", relShadow, " (", info.shadowLines, " lines)"
    else:
      echo "  (", stubs.len, " files, use --verbose to list)"
    echo ""

  # List gate runner shadows
  let gates = infos.filterIt(it.category == catGateRunner)
  if gates.len > 0:
    echo "=== Gate Runner Shadows (needs confirmation) ==="
    if verbose:
      for info in gates:
        let relShadow = info.shadowPath.replace(repoRoot & "/", "")
        echo "  ", relShadow, " (", info.shadowLines, " lines)"
    else:
      echo "  (", gates.len, " files, use --verbose to list)"
    echo ""

  # List other
  let others = infos.filterIt(it.category == catOther)
  if others.len > 0:
    echo "=== Other Shadows (manual review needed) ==="
    if verbose:
      for info in others:
        let relShadow = info.shadowPath.replace(repoRoot & "/", "")
        echo "  ", relShadow, " (", info.reason, ")"
    else:
      echo "  (", others.len, " files, use --verbose to list)"
    echo ""

  # Delete mode
  if deleteMode:
    echo "=== Deleting auto-generated shadows ==="
    var deleted = 0
    for info in autoGen:
      try:
        removeFile(info.shadowPath)
        deleted += 1
        stderr.writeLine("  Deleted: ", info.shadowPath)
      except IOError as e:
        stderr.writeLine("  Error deleting ", info.shadowPath, ": ", e.msg)
    echo "Deleted ", deleted, " files"
  else:
    echo "=== Dry Run (no files deleted) ==="
    echo "To delete auto-generated shadows, run with --delete"

when isMainModule:
  main()
